    _consume_keyword(tokens, "(")
    columns = []
    while tokens and tokens[0].type != TokenType.OPERATOR and tokens[0].value != ")":
        columns.append(_parse_column_def(tokens))
        if tokens and tokens[0].type == TokenType.OPERATOR and tokens[0].value == ",":
            _consume_token(tokens, TokenType.OPERATOR)
    _consume_keyword(tokens, ")")
    return CreateTableStmt(table_token.value, tuple(columns))
def _parse_drop_table(tokens):
    _consume_keyword(tokens, "DROP")
    _consume_keyword(tokens, "TABLE")
    table_token = _consume_token(tokens, TokenType.IDENTIFIER)
    return DropTableStmt(table_token.value)
def _parse_insert_stmt(tokens):
    _consume_keyword(tokens, "INSERT")
    _consume_keyword(tokens, "INTO")
    table_token = _consume_token(tokens, TokenType.IDENTIFIER)
    columns = None
    if tokens and tokens[0].type == TokenType.OPERATOR and tokens[0].value == "(":
        _consume_keyword(tokens, "(")
        columns = tuple(_parse_column_list(tokens))
        _consume_keyword(tokens, ")")
    _consume_keyword(tokens, "VALUES")
    _consume_keyword(tokens, "(")
    values = []
    while tokens and tokens[0].type != TokenType.OPERATOR and tokens[0].value != ")":
        if tokens[0].type == TokenType.INTEGER:
            token = _consume_token(tokens, TokenType.INTEGER)
            values.append(int(token.value))
        elif tokens[0].type == TokenType.STRING:
            token = _consume_token(tokens, TokenType.STRING)
            values.append(token.value)
        elif tokens[0].type == TokenType.KEYWORD:
            token = _consume_token(tokens, TokenType.KEYWORD)
            if token.value == "TRUE":
                values.append(True)
            elif token.value == "FALSE":
                values.append(False)
            elif token.value == "NULL":
                values.append(None)
            else:
                raise SQLSyntaxError(f"Unexpected keyword {token.value}")
        else:
            raise SQLSyntaxError(f"Unexpected token {tokens[0].type}")
        if tokens and tokens[0].type == TokenType.OPERATOR and tokens[0].value == ",":
            _consume_token(tokens, TokenType.OPERATOR)
    _consume_keyword(tokens, ")")
    return InsertStmt(table_token.value, columns, tuple(values))
def _parse_select_stmt(tokens):
    _consume_keyword(tokens, "SELECT")
    columns = None
    if tokens[0].type == TokenType.OPERATOR and tokens[0].value == "*":
        _consume_keyword(tokens, "*")
    else:
        columns = tuple(_parse_column_list(tokens))
    _consume_keyword(tokens, "FROM")
    table_token = _consume_token(tokens, TokenType.IDENTIFIER)
    where = None
    if tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "WHERE":
        _consume_keyword(tokens, "WHERE")
        where = _parse_expression(tokens)
    return SelectStmt(table_token.value, columns, where)
def _parse_delete_stmt(tokens):
    _consume_keyword(tokens, "DELETE")
    _consume_keyword(tokens, "FROM")
    table_token = _consume_token(tokens, TokenType.IDENTIFIER)
    where = None
    if tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "WHERE":
        _consume_keyword(tokens, "WHERE")
        where = _parse_expression(tokens)
    return DeleteStmt(table_token.value, where)
def parse(tokens: list[Token]) -> Statement:
    if tokens[0].type == TokenType.KEYWORD:
        if tokens[0].value == "CREATE":
            stmt = _parse_create_table(tokens)
        elif tokens[0].value == "DROP":
            stmt = _parse_drop_table(tokens)
        elif tokens[0].value == "INSERT":
            stmt = _parse_insert_stmt(tokens)
        elif tokens[0].value == "SELECT":
            stmt = _parse_select_stmt(tokens)
        elif tokens[0].value == "DELETE":
            stmt = _parse_delete_stmt(tokens)
        else:
            raise SQLSyntaxError(f"Unknown statement type {tokens[0].value}")
    else:
        raise SQLSyntaxError(f"Expected statement, got {tokens[0].type}")
    if tokens and tokens[0].type == TokenType.OPERATOR and tokens[0].value == ";":
        _consume_token(tokens, TokenType.OPERATOR)
    _consume_token(tokens, TokenType.EOF)
    return stmt
def parse_script(tokens: list[Token]) -> list[Statement]:
    stmts = []
    while tokens and tokens[0].type != TokenType.EOF:
        try:
            stmt = parse(tokens)
            if isinstance(stmt, (DropTableStmt, InsertStmt, SelectStmt, DeleteStmt)):
                stmts.append(stmt)
        except SQLSyntaxError:
            raise SQLSyntaxError("Malformed statement in script")
    _consume_token(tokens, TokenType.EOF)
    return stmts
